def test_per_head_quant_scales_backend_selection(
    backend_name: str, flash_attn_version: Literal[2, 3, 4] | None, should_succeed: bool
):
    """Test backend selection when use_per_head_quant_scales=True."""
    # Clear cache to ensure fresh backend selection
    _cached_get_attn_backend.cache_clear()

    attention_config = AttentionConfig(
        backend=AttentionBackendEnum[backend_name],
        flash_attn_version=flash_attn_version,
    )
    cache_config = CacheConfig(block_size=64)
    vllm_config = VllmConfig(
        attention_config=attention_config, cache_config=cache_config
    )

    if CudaPlatform is None:
        pytest.skip("CudaPlatform not available")
    with (
        set_current_vllm_config(vllm_config),
        patch("vllm.platforms.current_platform", CudaPlatform()),
    ):
        if backend_name == "FLASH_ATTN" and flash_attn_version == 3:
            if not torch.cuda.is_available():
                pytest.skip("FA3 requires CUDA")
            capability = torch.cuda.get_device_capability()
            if capability[0] != 9:
                pytest.skip("FA3 is only supported on Hopper (SM 9.x) GPUs")

        if should_succeed:
            backend = get_attn_backend(
                head_size=128,
                dtype=torch.float16,
                kv_cache_dtype="fp8",
                use_per_head_quant_scales=True,
            )
            assert backend.get_name() == backend_name
        else:
            with pytest.raises(ValueError) as exc_info:
                get_attn_backend(
                    head_size=128,
                    dtype=torch.float16,
                    kv_cache_dtype="fp8",
                    use_per_head_quant_scales=True,
                )
            assert backend_name in str(exc_info.value)

def test_fa4_hd256_fallback_matrix(kwargs, config_kwargs, expected):
    from vllm.v1.attention.backends.fa_utils import get_flash_attn_version

    kwargs = {
        "head_size": 256,
        "kv_cache_block_size": 128,
        "supports_fa4_hd256": True,
        **kwargs,
    }
    with _blackwell(_hd256_config(head_size=kwargs["head_size"], **config_kwargs)):
        assert get_flash_attn_version(**kwargs) == expected

def test_fa4_hd256_block_size_advertisement(
    backend_name: str, config_kwargs: dict, expected: int
):
    from vllm.v1.attention.backend import MultipleOf
    from vllm.v1.attention.backends.flash_attn import FlashAttentionBackend
    from vllm.v1.attention.backends.flash_attn_diffkv import (
        FlashAttentionDiffKVBackend,
    )

    backend = {
        "FLASH_ATTN": FlashAttentionBackend,
        "FLASH_ATTN_DIFFKV": FlashAttentionDiffKVBackend,
    }[backend_name]
    vllm_config = _hd256_config(**config_kwargs)
    with _blackwell(vllm_config):
        (size,) = backend.get_supported_kernel_block_sizes()
        preferred = backend.get_preferred_block_size(16)
    assert preferred == expected
    if expected == 128:
        assert size == 128
    else:
        assert isinstance(size, MultipleOf) and size.base == expected

def test_hash_routing_rejects_monolithic_without_support(
    dist_init, default_vllm_config, monkeypatch
):
    """A monolithic kernel that does not implement hash routing is rejected."""
    from vllm.model_executor.layers.fused_moe.experts.aiter_mxfp4_w4a16_moe import (
        AiterW4A16ExpertsMonolithic,
    )
    from vllm.model_executor.layers.fused_moe.oracle.mxfp4 import (
        select_deepseek_v4_mxfp4_moe_backend,
    )

    monkeypatch.setattr(
        AiterW4A16ExpertsMonolithic,
        "_supports_hash_routing",
        staticmethod(lambda: False),
    )
    _, config = _dsv4_moe_config(
        monkeypatch, default_vllm_config, True, "aiter_triton_mxfp4_bf16"
    )
    with pytest.raises(ValueError, match="hash routing"):
        select_deepseek_v4_mxfp4_moe_backend(config)

def test_aiter_w4a16_expert_parallel_selection(
    dist_init, default_vllm_config, monkeypatch, ep_config, supported
):
    """Naive EP (no all2all, no EPLB) selects the AITER W4A16 monolithic kernel,
    including on hash-routed layers."""
    from dataclasses import replace

    from vllm.model_executor.layers.fused_moe.oracle.mxfp4 import (
        select_deepseek_v4_mxfp4_moe_backend,
    )

    _, config = _dsv4_moe_config(
        monkeypatch, default_vllm_config, True, "aiter_triton_mxfp4_bf16"
    )
    config = replace(
        config, moe_parallel_config=replace(config.moe_parallel_config, **ep_config)
    )
    if supported:
        _, experts_cls = select_deepseek_v4_mxfp4_moe_backend(config)
        assert experts_cls is not None
        assert experts_cls.__name__ == "AiterW4A16ExpertsMonolithic"
    else:
        with pytest.raises(ValueError, match="parallel config"):
            select_deepseek_v4_mxfp4_moe_backend(config)

def test_x86_cpu_unquantized_kernel_selection(
    amx_supported: bool,
    in_dtype: torch.dtype,
    expect_amx_kernel: bool,
):
    from vllm.model_executor.layers.fused_moe.experts.cpu_moe import (
        CPUUnquantizedExperts,
        X86CPUUnquantizedExperts,
    )

    with (
        patch.object(current_platform, "is_cpu", return_value=True),
        patch.object(
            current_platform,
            "get_cpu_architecture",
            return_value=CpuArchEnum.X86,
        ),
        patch("torch.cpu._is_amx_tile_supported", return_value=amx_supported),
    ):
        moe_config = make_dummy_moe_config(
            hidden_dim=128,
            intermediate_size=128,
            in_dtype=in_dtype,
        )
        kernel_cls = next(
            cls
            for cls in backend_to_kernel_cls(UnquantizedMoeBackend.CPU)
            if cls.is_supported_config(
                cls,
                moe_config,
                None,
                None,
                CPUUnquantizedExperts.activation_format(),
            )[0]
        )

    expected_kernel_cls = (
        X86CPUUnquantizedExperts if expect_amx_kernel else CPUUnquantizedExperts
    )
    assert kernel_cls is expected_kernel_cls

